	if err != nil {
		return fmt.Errorf("failed to fetch user from db: %w", err)
	}

	userJWT := dto.UserJWTFromUserModel(userModel)

	var jwtOpts []session.JWTOptions
	if c.Stash().Get(StashPathAMRValues).Exists() {
		var amr []string
		for _, v := range c.Stash().Get(StashPathAMRValues).Array() {
			if s := v.String(); s != "" {
				amr = append(amr, s)
			}
		}
		if len(amr) > 0 {
			jwtOpts = append(jwtOpts, session.WithValue("amr", amr))
		}
	}

	signedSessionToken, rawToken, err := deps.SessionManager.GenerateJWT(userJWT, deps.TenantID, jwtOpts...)
	if err != nil {
		return fmt.Errorf("failed to generate JWT: %w", err)
	}

	claims, err := dto.GetClaimsFromToken(rawToken)
	if err != nil {
		return fmt.Errorf("failed to get token claims: %w", err)
	}

	err = c.Payload().Set("claims", claims)
	if err != nil {
		return fmt.Errorf("failed to set token claims to payload: %w", err)
	}

	activeSessions, err := deps.Persister.GetSessionPersisterWithConnection(deps.Tx).ListActive(userId, deps.TenantID)
	if err != nil {
		return fmt.Errorf("failed to list active sessions: %w", err)
	}

	// remove all server side sessions that exceed the limit
	if len(activeSessions) >= deps.Cfg.Session.Limit {
		for i := deps.Cfg.Session.Limit - 1; i < len(activeSessions); i++ {
			err = deps.Persister.GetSessionPersisterWithConnection(deps.Tx).Delete(activeSessions[i])
			if err != nil {
				return fmt.Errorf("failed to remove latest session: %w", err)
			}

			err = utils.TriggerWebhooks(deps.HttpContext, deps.Tx, deps.TenantID, events.SessionDeletePassiveLimit, activeSessions[i])
			if err != nil {
				return fmt.Errorf("failed to trigger webhook: %w", err)
			}
		}
	}

	sessionID, _ := rawToken.Get("session_id")

	expirationTime := rawToken.Expiration()
