		if err != nil {
			return fmt.Errorf("failed to convert session id to uuid: %w", err)
		}
		sessionModel, err := h.persister.GetSessionPersister().Get(sessionID, tenant.ID)
		if err != nil {
			return fmt.Errorf("failed to get session from database: %w", err)
		}
