	defer s.mu.RUnlock()

	device, ok := s.devices[deviceKey(tenantID, userID, deviceID)]
	if !ok {
		return nil, nil
	}
	return cloneDevice(device), nil
}

func (s *MemoryStore) FindDeviceByCredential(_ context.Context, tenantID, userID, credentialID string) (*Device, error) {
	s.mu.RLock()
