package migration

import (
	"net/http"

	"github.com/gofrs/uuid"
	"github.com/lestrrat-go/jwx/v2/jwt"
	"github.com/teamhanko/hanko/backend/v3/dto"
	"github.com/teamhanko/hanko/backend/v3/session"
)

const (
	ClaimDeviceID    = "did"
	ClaimRelation    = "drel"
	ClaimTrustLevel  = "trust_level"
	ClaimRecovered   = "passkey_recovered"
)

// JWTOptions adds optional device claims to the existing Hanko session JWT.
// Unknown claims are ignored by older consumers and by JWT verification, so
// sessions without these claims keep working.
func (c SessionClaims) JWTOptions() []session.JWTOptions {
	options := make([]session.JWTOptions, 0, 4)
	if c.DeviceID != "" {
		options = append(options, session.WithValue(ClaimDeviceID, c.DeviceID))
	}
	if c.Relation != "" {
		options = append(options, session.WithValue(ClaimRelation, string(c.Relation)))
	}
	if c.TrustLevel != "" {
		options = append(options, session.WithValue(ClaimTrustLevel, c.TrustLevel))
	}
	if c.Recovered {
		options = append(options, session.WithValue(ClaimRecovered, true))
	}
	return options
}

// IssueSession creates the same signed JWT and cookie used by the existing
// session system. Recovery/migration only changes claims, not the token type.
func IssueSession(manager session.Manager, user dto.UserJWT, tenantID uuid.UUID, claims SessionClaims) (string, jwt.Token, *http.Cookie, error) {
	token, rawToken, err := manager.GenerateJWT(user, tenantID, claims.JWTOptions()...)
	if err != nil {
		return "", nil, nil, err
	}
	cookie, err := manager.GenerateCookie(token)
	if err != nil {
		return "", nil, nil, err
	}
	return token, rawToken, cookie, nil
}

// SessionClaimsFromToken extracts the optional device claims. Missing claims
// produce the zero value and therefore represent a legacy session.
func SessionClaimsFromToken(token jwt.Token) SessionClaims {
	claims := SessionClaims{}
	if token == nil {
		return claims
	}
	if value, ok := token.Get(ClaimDeviceID); ok {
		claims.DeviceID, _ = value.(string)
	}
	if value, ok := token.Get(ClaimRelation); ok {
		if relation, ok := value.(string); ok {
			claims.Relation = Relation(relation)
		}
	}
	if value, ok := token.Get(ClaimTrustLevel); ok {
		claims.TrustLevel, _ = value.(string)
	}
	if value, ok := token.Get(ClaimRecovered); ok {
		claims.Recovered, _ = value.(bool)
	}
	return claims
}

